using BYSResults;
using Microsoft.EntityFrameworkCore;
using Day32Practice.Data;
using Day32Practice.Models;

namespace Day32Practice.Services;

/// <summary>
/// [PRE-BUILT] Reference implementation — you do not edit this file.
///
/// This is the same shape as Lab 3's RestockService
/// (Workflows/ProductRestock/Services/RestockService.cs). It is here for two reasons:
///
/// 1. `Day32Practice.Tests/RestockServiceTests.cs` uses it as the reference test subject.
///    Run that one test first. It proves the SqliteDbFactory harness really works before
///    you write your own tests in Practice 3.
/// 2. It shows the Day 27 transaction pattern and the Day 32 concurrency pattern together
///    in one method — which is exactly what Lab 3 asks each workflow service to do.
/// </summary>
public class RestockService(StoreDbContext context) : IRestockService
{
    private readonly StoreDbContext _context = context;

    /// <summary>
    /// Adds units to a product's stock inside an explicit transaction.
    /// The shape is Begin → work → ONE SaveChangesAsync → Commit.
    /// On a concurrency conflict: Rollback, then Clear the change tracker.
    /// </summary>
    public async Task<Result<Product>> RestockProductAsync(int productId, int quantity)
    {
        var result = new Result<Product>();

        if (quantity <= 0)
        {
            result.AddError(new Error("InvalidQuantity", "Restock quantity must be greater than zero."));
            return result;
        }

        using var transaction = await _context.Database
            .BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted);
        try
        {
            var product = await _context.Products.FindAsync(productId);
            if (product is null)
            {
                result.AddError(new Error("ProductNotFound", $"Product with ID {productId} not found."));
                return result;
            }

            product.StockQuantity += quantity;

            await _context.SaveChangesAsync(); // the RowVersion check happens here
            await transaction.CommitAsync();

            return result.WithValue(product);
        }
        catch (DbUpdateConcurrencyException)
        {
            await transaction.RollbackAsync();
            _context.ChangeTracker.Clear();
            result.AddError(new Error("ConcurrencyConflict",
                "Another user modified this product. Please reload and try again."));
            return result;
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync();
            _context.ChangeTracker.Clear();
            result.AddError(new Error("RestockFailed", $"Restock operation failed: {ex.Message}"));
            return result;
        }
    }
}
